require_once dirname(__DIR__) . '/_common.php';$id=isset($_GET['id'])?(int)$_GET['id']:0;$stmt=$pdo->prepare('SELECT * FROM kegiatan WHERE id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){osis_set_flash('error','Kegiatan tidak ditemukan.');osis_redirect('admin/kegiatan/index.php');}$pageTitle='Edit kegiatan';$error='';$statuses=['rencana','berlangsung','selesai'];
if(osis_admin_is_post()){osis_verify_csrf();$judul=osis_post_string('judul',180);$deskripsi=osis_post_string('deskripsi',10000);$tanggal=osis_post_string('tanggal',10);$lokasi=osis_post_string('lokasi',150);$status=isset($_POST['status'])?(string)$_POST['status']:'rencana';if($judul===''||$deskripsi===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal)||!in_array($status,$statuses,true)){$error='Judul, deskripsi, tanggal, dan status harus diisi dengan benar.';}else{try{$gambar=osis_store_uploaded_image(isset($_FILES['gambar'])?$_FILES['gambar']:null,'kegiatan');$sql='UPDATE kegiatan SET judul=?,deskripsi=?,tanggal=?,lokasi=?,status=?'.($gambar?',gambar=?':'').' WHERE id=?';$params=[$judul,$deskripsi,$tanggal,$lokasi?:null,$status];if($gambar)$params[]=$gambar;$params[]=$id;$pdo->prepare($sql)->execute($params);if($gambar)osis_delete_uploaded_file($item['gambar']);osis_log_activity('Memperbarui kegiatan: '.$judul);osis_set_flash('success','Kegiatan berhasil diperbarui.');osis_redirect('admin/kegiatan/index.php');}catch(Throwable $exception){$error=osis_admin_handle_error($exception);}}}
osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap"><a class="back-link" href="<?=osis_e(osis_url('admin/kegiatan/index.php'))?>">← Daftar kegiatan</a><div class="admin-panel form-panel"><span class="eyebrow">PERBARUI AGENDA</span><h2>Edit kegiatan</h2><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" data-validate-form><?=osis_csrf_input()?><label for="judul">Nama kegiatan</label><input id="judul" name="judul" required maxlength="180" value="<?=osis_e(isset($_POST['judul'])?$_POST['judul']:$item['judul'])?>"><label for="deskripsi">Deskripsi</label><textarea id="deskripsi" name="deskripsi" rows="7" required><?=osis_e(isset($_POST['deskripsi'])?$_POST['deskripsi']:$item['deskripsi'])?></textarea><div class="form-grid"><div><label for="tanggal">Tanggal</label><input id="tanggal" name="tanggal" type="date" required value="<?=osis_e(isset($_POST['tanggal'])?$_POST['tanggal']:$item['tanggal'])?>"></div><div><label for="lokasi">Lokasi</label><input id="lokasi" name="lokasi" maxlength="150" value="<?=osis_e(isset($_POST['lokasi'])?$_POST['lokasi']:$item['lokasi'])?>"></div><div><label for="status">Status</label><select id="status" name="status"><?php foreach($statuses as $status):?><option value="<?=osis_e($status)?>" <?=isset($_POST['status'])?($_POST['status']===$status?'selected':''):($item['status']===$status?'selected':'')?>><?=osis_e(ucfirst($status))?></option><?php endforeach;?></select></div></div><?php if($item['gambar']):?><div class="current-upload"><img src="<?=osis_e(osis_image_url($item['gambar']))?>" alt="Gambar saat ini"><span>Gambar saat ini</span></div><?php endif;?><label for="gambar">Ganti gambar <span class="optional">JPG, PNG, WEBP · maks. 5 MB</span></label><input id="gambar" name="gambar" type="file" accept="image/jpeg,image/png,image/webp"><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/kegiatan/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Simpan perubahan <span>↗</span></button></div></form></div></div>
